char *concatenateData(int Ui, const std::vector<std::string> &Oi, const std::vector<std::string> &Ri, const char *Ts)
{
    std::string op_list="";
    for (int i = 0; i < Oi.size();i++){
        op_list += Oi[i];
    }

    std::string resc_list = "";
    for (int i = 0; i < Ri.size();i++){
        resc_list += Ri[i];
    }

    char* res = new char[500];
    snprintf(res, 500, "%d%s%s%s", Ui, op_list.c_str(), resc_list.c_str(), Ts);
    return res;
}
char *hashing(char *str, int strlength, big hash){ /* compute hash function */
    static char h[32];
    int ch;
    sha sh;
    shs256_init(&sh);
    for (int i = 0; i < strlength; i++)
    {
        ch = str[i];
        shs256_process(&sh, ch);
    }

    shs256_hash(&sh, h);
    bytes_to_big(32, h, hash);
    return h;
}

big generateVerificationPoint(const char *GAij, const char *Si){
    char vp[1000];
    snprintf(vp, sizeof(vp), "%s%s", GAij, Si);
    big VPij = mirvar(1);
    hashing(vp, strlen(vp), VPij);

    return VPij;
}

bool checkVerificationPoint(struct bloom * bloom, big check_vp){
    char check_vps[1000];
    cotstr(check_vp, check_vps);
    int check_len = strlen(check_vps);
    bool granted = false;
    if (bloom_check(bloom, &check_vps, check_len))
    {
        granted = true;
        printf("\n\nIt may be there!\n");
    }
    else
    {
        printf("\n\nIts not there!\n");
    }

    return granted;
}

void addVerificationPoint(struct bloom * bloom, big VPij){
    char vps[1000];
    cotstr(VPij, vps);
    int len = strlen(vps);

    bloom_add(bloom, &vps, len);
}



big secret_seed_generator(){
    big random = mirvar(0);
    big q = mirvar(9000); // The range is from 0 to 8999
    time_t t;
    time(&t); // Get the current time
    irand((unsigned long)t); // Seed the random number generator
    
    // Generate a random number less than 9000
    bigrand(q, random);

    // Add 1000 to the random number to ensure it's 4 digits
    add(random, mirvar(1000), random);

    mirkill(q);
    return random;
}

big secret_seed_generator_big(int userid, big p, big g, big q)
{
    big random = mirvar(1);
    big userid_big = mirvar(1);
    convert(userid, userid_big);
    srand(time(0)); // use current time as seed
    long seed = rand();
    irand(seed);
    bigrand(q, random);

    big temp = mirvar(1);
    add(userid_big, random, temp);
    big result = mirvar(1);
    powmod(g, temp, p, result);

    return result;
}
big read_secret(int userid) {
    char filename[256];
    snprintf(filename, sizeof(filename), "secret_seed/secret_seed_%d.txt", userid);
    FILE *file = fopen(filename, "r");
    if(file == NULL){
        big seeds = secret_seed_generator();
        file = fopen(filename, "w");

        // Print the big number to the file
        cotnum(seeds, file);

        // Close the file
        fclose(file);

        file = fopen(filename, "r");
    }
    
    big secret = mirvar(0);
    // cinnum(secret,file);
    cinnum(secret, file);
    return secret;
}

void secret_generate(){

    srand(time(0));
    long seed = rand();
    irand(seed);
    
    for (int i = 10001; i <= 10015;i++){
        int userid = i;
        big seeds = secret_seed_generator();
        cotnum(seeds, stdout);
        char filename[256];
        snprintf(filename, sizeof(filename), "secret_seed/secret_seed_%d.txt", userid);
        FILE *file = fopen(filename, "w");

        // Print the big number to the file
        cotnum(seeds, file);

        // Close the file
        fclose(file);
    }
}

