    size_t len = strlen(bf);
    // std::cout<<bf<<std::endl;
    // std::cout<<len<<std::endl;
    if(len>0 && bf[len-1] == '\n'){
        // std::cout<<"1\n";
        bf[len-1] = '\0';
        std::string latest_bloom(bf);
        convert_from_hexadecimal(&bloom,latest_bloom);
    }
    else if(len>0){
        // std::cout<<"2\n";
        std::string latest_bloom(bf);
        convert_from_hexadecimal(&bloom,latest_bloom);
    }
    fclose(params);


    // retrive the latest bloom filter
    // std::string latest_bloom = getRequest();
    // if(latest_bloom != "No Event"){
    //     // convert bloom from hexadecimal (API) to unsigned char and assign to bloom->bf
    //     convert_from_hexadecimal(&bloom, latest_bloom);
    // }

    big ga_temp = mirvar(1);
    // // check granted access history
    // char verif_file_temp[256];
    // sprintf(verif_file_temp, "granted_access/%d/%s", Ui,SGAi);
    // std::cout << "===============================================\n";
    // FILE *file_temp = fopen(verif_file_temp, "r");
    // cinnum(ga_temp, file_temp);

    // fclose(file_temp);

    char ga_history[300];
    cotstr(ga_temp, ga_history);
    snprintf(ga_history,300,"%s", SGAi.c_str());

    //compute VPs History to Check
    big check_vp = generateVerificationPoint(ga_history, Si);

    if(!checkVerificationPoint(&bloom, check_vp)){
        snprintf(result, 100, "Access Denied");
        return result;
    }

    // Concatenate data
    char* data = new char[500];
    snprintf(data, 500, "%s", concatenateData(Ui, Oi, Ri, Ts));

