    if(len>0 && bf[len-1] == '\n'){
        bf[len-1] = '\0';
        std::string latest_bloom(bf);
        convert_from_hexadecimal(&bloom,latest_bloom);
    }
    else if(len>0){
        std::string latest_bloom(bf);
        convert_from_hexadecimal(&bloom,latest_bloom);
    }
    fclose(params);

    // Concatenate data
    char* data = new char[500];
    snprintf(data, 500, "%s", concatenateData(Ui, Oi, Ri, Ts));

    big res;
    res = mirvar(1);
    hashing(data, strlen(data), res);

    char GAij[300];
    // cotnum(res, stdout);

    cotstr(res, GAij);

    big VPij = generateVerificationPoint(GAij, Si);

    cotnum(VPij, stdout);

    //save new verificationpoint
    // char verif_file_path[256];
    // sprintf(verif_file_path, "verification_point/verification_point_%d_%s.txt", Ui, Ts);
    // FILE *verif_file = fopen(verif_file_path, "w");
    // cotnum(VPij, verif_file);
    
    // fclose(verif_file);

    addVerificationPoint(&bloom, VPij);

    FILE *params2 = fopen("bf.txt","w");
    std::string bf_write = convert_to_hexadecimal(bloom.bf, bloom.bytes);
    fwrite(bf_write.c_str(), sizeof(char), bf_write.size(), params2);
    fclose(params2);


